def P(text,style='BodyPL'):
    # Polskie znaki zachowujemy; separatory typograficzne normalizujemy do ASCII.
    text=str(text).replace('–','-').replace('—','-').replace('−','-').replace('→',' -> ').replace('×',' x ').replace('≥','>=')
    return Paragraph(html.escape(text).replace('\n','<br/>'),styles[style])
def H(text):return P(text,'HeadingPL')
def tbl(headers,rows,widths):
    t=Table([[P(x,'LabelPL') for x in headers]]+[[P(x,'SmallPL') for x in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#24354D')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#EFF3F8'),colors.white]),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#CBD4E1'))]))
    return t
def stamp(iso):
    if not iso:return 'w toku'
    dt=datetime.fromisoformat(iso.replace('Z','+00:00')).astimezone(timezone(timedelta(hours=1)))
    return dt.strftime('%d.%m.%Y %H:%M:%S CET')
class NumberedCanvas(canvas.Canvas):
    def __init__(self,*args,**kwargs):super().__init__(*args,**kwargs);self.saved=[]
    def showPage(self):self.saved.append(dict(self.__dict__));self._startPage()
    def save(self):
        n=len(self.saved)
        for state in self.saved:
            self.__dict__.update(state)
            self.setStrokeColor(colors.HexColor('#CBD4E1'));self.line(42,39,A4[0]-42,39)
            self.setFont('Arial',8);self.setFillColor(colors.HexColor('#536174'))
            self.drawString(42,26,'Kamil Andrzejewski | nr studenta 83741 | projekt QA | 13.11.2026')
            self.drawRightString(A4[0]-42,26,f'{self._pageNumber} / {n}')
            super().showPage()
        super().save()
def write(name,story):
    doc=SimpleDocTemplate(str(ROOT/name),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=42,bottomMargin=54,title=name.replace('.pdf',''),author='Kamil Andrzejewski, nr studenta 83741',pageCompression=1)
    doc.build(story,canvasmaker=NumberedCanvas)

